CREATE TABLE public.satellite_ingestion_control (scope text NOT NULL CHECK(scope IN ('global','provider','vineyard','pixels','publisher')),scope_key text NOT NULL,enabled boolean NOT NULL DEFAULT false,reason text NOT NULL DEFAULT 'Awaiting capped pilot validation',changed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,scope_key));
GRANT ALL ON public.satellite_ingestion_control TO service_role;
ALTER TABLE public.satellite_ingestion_control ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_only ON public.satellite_ingestion_control TO service_role USING(true) WITH CHECK(true);
CREATE TABLE public.satellite_acquisitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text NOT NULL,collection text NOT NULL,provider_scene_id text NOT NULL,acquired_at timestamptz NOT NULL,source_manifest jsonb NOT NULL,source_manifest_hash text NOT NULL CHECK(source_manifest_hash ~ '^[a-f0-9]{64}$'),provenance_version integer NOT NULL DEFAULT 1 CHECK(provenance_version=1),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,collection,provider_scene_id,source_manifest_hash),CHECK(jsonb_typeof(source_manifest)='object'));
GRANT ALL ON public.satellite_acquisitions TO service_role;
ALTER TABLE public.satellite_acquisitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_only ON public.satellite_acquisitions TO service_role USING(true) WITH CHECK(true);
CREATE FUNCTION public.satellite_acquisition_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Acquisition manifests are immutable'; END $$;
CREATE TRIGGER immutable_acquisition BEFORE UPDATE OR DELETE ON public.satellite_acquisitions FOR EACH ROW EXECUTE FUNCTION public.satellite_acquisition_immutable();
CREATE TABLE public.satellite_work_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vineyard_id uuid NOT NULL,paddock_id uuid NOT NULL,acquisition_id uuid NOT NULL REFERENCES public.satellite_acquisitions(id) ON DELETE RESTRICT,layer text NOT NULL CHECK(layer IN ('NDVI','TRUE_COLOUR')),processing_version text NOT NULL DEFAULT 'sentinel2-v7-exact-native-pilot',lane text NOT NULL DEFAULT 'fresh' CHECK(lane IN ('fresh','backfill')),status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','leased','retry','verified','dead','cancelled')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),due_at timestamptz NOT NULL DEFAULT now(),lease_token uuid,lease_expires_at timestamptz,heartbeat_at timestamptz,boundary_snapshot jsonb NOT NULL,boundary_hash text NOT NULL CHECK(boundary_hash ~ '^[a-f0-9]{64}$'),output_manifest jsonb,last_error text,created_at timestamptz NOT NULL DEFAULT now(),verified_at timestamptz,UNIQUE(vineyard_id,paddock_id,acquisition_id,layer,processing_version),CHECK(vineyard_id='fe952afe-437f-4be7-8cbf-fdd8e630411c'::uuid));
GRANT ALL ON public.satellite_work_items TO service_role;
ALTER TABLE public.satellite_work_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_only ON public.satellite_work_items TO service_role USING(true) WITH CHECK(true);
CREATE INDEX satellite_work_due ON public.satellite_work_items(status,due_at,lane);
CREATE TABLE public.satellite_provider_budget (provider text NOT NULL,period_start date NOT NULL,period_kind text NOT NULL CHECK(period_kind IN ('day','month')),request_limit bigint NOT NULL DEFAULT 0 CHECK(request_limit>=0),requests_reserved bigint NOT NULL DEFAULT 0 CHECK(requests_reserved>=0),processing_limit numeric NOT NULL DEFAULT 0 CHECK(processing_limit>=0),processing_reserved numeric NOT NULL DEFAULT 0 CHECK(processing_reserved>=0),cpu_ms_limit bigint NOT NULL DEFAULT 0 CHECK(cpu_ms_limit>=0),cpu_ms_reserved bigint NOT NULL DEFAULT 0 CHECK(cpu_ms_reserved>=0),transfer_limit bigint NOT NULL DEFAULT 0 CHECK(transfer_limit>=0),transfer_reserved bigint NOT NULL DEFAULT 0 CHECK(transfer_reserved>=0),storage_limit bigint NOT NULL DEFAULT 0 CHECK(storage_limit>=0),storage_reserved bigint NOT NULL DEFAULT 0 CHECK(storage_reserved>=0),hard_spend_limit numeric NOT NULL DEFAULT 0 CHECK(hard_spend_limit>=0),spend_reserved numeric NOT NULL DEFAULT 0 CHECK(spend_reserved>=0),currency text NOT NULL DEFAULT 'AUD',approved_at timestamptz,PRIMARY KEY(provider,period_start,period_kind));
GRANT ALL ON public.satellite_provider_budget TO service_role;
ALTER TABLE public.satellite_provider_budget ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_only ON public.satellite_provider_budget TO service_role USING(true) WITH CHECK(true);
CREATE TABLE public.satellite_provider_throttle (provider text PRIMARY KEY,next_allowed_at timestamptz NOT NULL DEFAULT now(),retry_after_until timestamptz,min_interval_ms integer NOT NULL DEFAULT 1000 CHECK(min_interval_ms>0),slot_token uuid,slot_expires_at timestamptz,rate_limited_count bigint NOT NULL DEFAULT 0);
GRANT ALL ON public.satellite_provider_throttle TO service_role;
ALTER TABLE public.satellite_provider_throttle ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_only ON public.satellite_provider_throttle TO service_role USING(true) WITH CHECK(true);
CREATE TABLE public.satellite_freshness (vineyard_id uuid NOT NULL,paddock_id uuid NOT NULL,provider text NOT NULL,processing_version text NOT NULL,last_provider_check_at timestamptz,newest_discovered_at timestamptz,newest_usable_at timestamptz,newest_verified_complete_at timestamptz,PRIMARY KEY(vineyard_id,paddock_id,provider,processing_version));
GRANT ALL ON public.satellite_freshness TO service_role;
ALTER TABLE public.satellite_freshness ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_only ON public.satellite_freshness TO service_role USING(true) WITH CHECK(true);
CREATE TABLE public.satellite_ingest_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('discovery','worker')),correlation_id uuid NOT NULL UNIQUE,vineyard_id uuid NOT NULL DEFAULT 'fe952afe-437f-4be7-8cbf-fdd8e630411c',started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,heartbeat_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'received',reason text,provider_calls integer NOT NULL DEFAULT 0,no_op boolean NOT NULL DEFAULT true);
GRANT ALL ON public.satellite_ingest_runs TO service_role;
ALTER TABLE public.satellite_ingest_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_only ON public.satellite_ingest_runs TO service_role USING(true) WITH CHECK(true);
ALTER TABLE public.satellite_scenes ADD COLUMN acquisition_id uuid REFERENCES public.satellite_acquisitions(id) ON DELETE RESTRICT;
ALTER TABLE public.satellite_raster_assets ADD COLUMN provenance jsonb,ADD COLUMN verified_at timestamptz,ADD COLUMN byte_size bigint,ADD COLUMN content_sha256 text;
ALTER TABLE public.satellite_index_summaries ADD COLUMN analysis_provenance jsonb;
ALTER TABLE public.satellite_raster_assets ADD CONSTRAINT satellite_verified_proof CHECK(verified_at IS NULL OR(byte_size>0 AND content_sha256 ~ '^[a-f0-9]{64}$' AND jsonb_typeof(provenance)='object' AND provenance->>'schema_version'='1'));
CREATE FUNCTION public.satellite_pipeline_enabled(p_vineyard uuid,p_provider text,p_pixels boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT p_vineyard='fe952afe-437f-4be7-8cbf-fdd8e630411c'::uuid AND NOT EXISTS(SELECT 1 FROM (VALUES('global','all'),('vineyard',p_vineyard::text),('provider',p_provider)) AS required(s,k) WHERE NOT EXISTS(SELECT 1 FROM public.satellite_ingestion_control c WHERE c.scope=required.s AND c.scope_key=required.k AND c.enabled)) AND(NOT p_pixels OR EXISTS(SELECT 1 FROM public.satellite_ingestion_control WHERE scope='pixels' AND scope_key='all' AND enabled)); $$;
REVOKE ALL ON FUNCTION public.satellite_pipeline_enabled(uuid,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.satellite_pipeline_enabled(uuid,text,boolean) TO service_role;
CREATE FUNCTION public.satellite_claim_work(p_vineyard uuid,p_provider text) RETURNS SETOF public.satellite_work_items LANGUAGE plpgsql SET search_path=public AS $$ DECLARE picked uuid; BEGIN IF NOT public.satellite_pipeline_enabled(p_vineyard,p_provider,true) THEN RETURN; END IF; UPDATE public.satellite_work_items w SET status=CASE WHEN attempts>=5 THEN 'dead' ELSE 'retry' END,lease_token=NULL,lease_expires_at=NULL,last_error='Lease expired',due_at=now() FROM public.satellite_acquisitions a WHERE w.acquisition_id=a.id AND w.vineyard_id=p_vineyard AND a.provider=p_provider AND w.status='leased' AND w.lease_expires_at<now(); SELECT w.id INTO picked FROM public.satellite_work_items w JOIN public.satellite_acquisitions a ON a.id=w.acquisition_id WHERE w.vineyard_id=p_vineyard AND a.provider=p_provider AND w.status IN ('queued','retry') AND w.due_at<=now() AND w.attempts<5 ORDER BY CASE w.lane WHEN 'fresh' THEN 0 ELSE 1 END,a.acquired_at DESC,w.created_at FOR UPDATE OF w SKIP LOCKED LIMIT 1; IF picked IS NULL THEN RETURN; END IF; RETURN QUERY UPDATE public.satellite_work_items SET status='leased',attempts=attempts+1,lease_token=gen_random_uuid(),lease_expires_at=now()+interval '90 seconds',heartbeat_at=now() WHERE id=picked RETURNING *; END $$;
REVOKE ALL ON FUNCTION public.satellite_claim_work(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.satellite_claim_work(uuid,text) TO service_role;
CREATE FUNCTION public.satellite_finish_work(p_id uuid,p_token uuid,p_status text,p_result jsonb DEFAULT NULL,p_error text DEFAULT NULL,p_retry_ms integer DEFAULT 30000) RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$ DECLARE changed integer; BEGIN IF p_status NOT IN ('verified','retry','dead','cancelled') THEN RAISE EXCEPTION 'Invalid terminal status'; END IF; IF p_status='verified' AND(p_result IS NULL OR p_result->>'schema_version'<>'1' OR p_result->>'verified'<>'true' OR p_result->>'boundary_hash' IS NULL) THEN RAISE EXCEPTION 'Missing verification proof'; END IF; UPDATE public.satellite_work_items w SET status=CASE WHEN p_status='retry' AND attempts>=5 THEN 'dead' ELSE p_status END,output_manifest=p_result,last_error=left(p_error,500),due_at=now()+make_interval(secs=>greatest(1,least(p_retry_ms,86400000))/1000.0),verified_at=CASE WHEN p_status='verified' THEN now() ELSE NULL END,lease_token=NULL,lease_expires_at=NULL WHERE w.id=p_id AND w.status='leased' AND w.lease_token=p_token AND w.lease_expires_at>now() AND(p_status<>'verified' OR(p_result->>'boundary_hash'=w.boundary_hash AND p_result->>'acquisition_id'=w.acquisition_id::text AND p_result->>'layer'=w.layer)); GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed=1; END $$;
REVOKE ALL ON FUNCTION public.satellite_finish_work(uuid,uuid,text,jsonb,text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.satellite_finish_work(uuid,uuid,text,jsonb,text,integer) TO service_role;
CREATE FUNCTION public.satellite_reserve_provider(p_provider text,p_vineyard uuid,p_requests bigint,p_processing numeric,p_cpu bigint,p_transfer bigint,p_storage bigint,p_spend numeric,p_pixels boolean DEFAULT true) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE d date:=(now() AT TIME ZONE 'UTC')::date; m date:=date_trunc('month',now() AT TIME ZONE 'UTC')::date; b public.satellite_provider_budget; t public.satellite_provider_throttle; n integer:=0; token uuid:=gen_random_uuid(); BEGIN IF least(p_requests,p_processing,p_cpu,p_transfer,p_storage,p_spend)<0 OR NOT public.satellite_pipeline_enabled(p_vineyard,p_provider,p_pixels) THEN RETURN NULL; END IF; SELECT * INTO t FROM public.satellite_provider_throttle WHERE provider=p_provider FOR UPDATE; IF NOT FOUND OR t.next_allowed_at>now() OR t.retry_after_until>now() OR t.slot_expires_at>now() THEN RETURN NULL; END IF; FOR b IN SELECT * FROM public.satellite_provider_budget WHERE provider=p_provider AND((period_kind='day' AND period_start=d) OR(period_kind='month' AND period_start=m)) ORDER BY period_kind FOR UPDATE LOOP n:=n+1; IF b.approved_at IS NULL OR b.hard_spend_limit<=0 OR b.requests_reserved+p_requests>b.request_limit OR b.processing_reserved+p_processing>b.processing_limit OR b.cpu_ms_reserved+p_cpu>b.cpu_ms_limit OR b.transfer_reserved+p_transfer>b.transfer_limit OR b.storage_reserved+p_storage>b.storage_limit OR b.spend_reserved+p_spend>b.hard_spend_limit THEN RETURN NULL; END IF; END LOOP; IF n<>2 THEN RETURN NULL; END IF; UPDATE public.satellite_provider_budget SET requests_reserved=requests_reserved+p_requests,processing_reserved=processing_reserved+p_processing,cpu_ms_reserved=cpu_ms_reserved+p_cpu,transfer_reserved=transfer_reserved+p_transfer,storage_reserved=storage_reserved+p_storage,spend_reserved=spend_reserved+p_spend WHERE provider=p_provider AND((period_kind='day' AND period_start=d) OR(period_kind='month' AND period_start=m)); UPDATE public.satellite_provider_throttle SET slot_token=token,slot_expires_at=now()+interval '90 seconds',next_allowed_at=now()+make_interval(secs=>min_interval_ms/1000.0) WHERE provider=p_provider; RETURN token; END $$;
REVOKE ALL ON FUNCTION public.satellite_reserve_provider(text,uuid,bigint,numeric,bigint,bigint,bigint,numeric,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.satellite_reserve_provider(text,uuid,bigint,numeric,bigint,bigint,bigint,numeric,boolean) TO service_role;
CREATE FUNCTION public.satellite_release_provider(p_provider text,p_token uuid,p_retry_ms integer DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$ DECLARE changed integer; BEGIN UPDATE public.satellite_provider_throttle SET slot_token=NULL,slot_expires_at=NULL,retry_after_until=CASE WHEN p_retry_ms IS NULL THEN retry_after_until ELSE greatest(coalesce(retry_after_until,now()),now()+make_interval(secs=>greatest(0,least(p_retry_ms,86400000))/1000.0)) END,rate_limited_count=rate_limited_count+CASE WHEN p_retry_ms IS NULL THEN 0 ELSE 1 END WHERE provider=p_provider AND slot_token=p_token; GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed=1; END $$;
REVOKE ALL ON FUNCTION public.satellite_release_provider(text,uuid,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.satellite_release_provider(text,uuid,integer) TO service_role;
COMMENT ON TABLE public.satellite_work_items IS 'Isolated disabled Stockmans Ridge pilot; never seed from legacy backfill. verified means staged outputs, not legacy publication.';
COMMENT ON TABLE public.satellite_ingestion_control IS 'Missing controls fail closed. Rollback: disable all rows and entrypoints; retain history and additions.';